mapper.select:
/* selectReqList - Lee MS */
SELECT A.CMIT_SE_CD AS CMIT_SE_CD, A.ESNTL_LINK_INST_SE_CD AS ESNTL_LINK_INST_SE_CD, B.INST_NM AS INST_NM, C##RG.DEC_B64(A.ENTRST_PIC_NM_ENCPT) AS ENTRST_PIC_NM, A.CMIT_JBTTL_SE_CD AS CMIT_JBTTL_SE_CD, A.NOW_ACTVT_YN AS NOW_ACTVT_YN, A.JBTTL_NM AS JBTTL_NM, A.ESNTL_LINK_MNG_NO AS ESNTL_LINK_MNG_NO, A.CMIT_CNSTTN_MNG_NO AS CMIT_CNSTTN_MNG_NO FROM ACA610 A, ACA600 B /*필수연계기관(B) */ WHERE A.ESNTL_LINK_MNG_NO = B.ESNTL_LINK_MNG_NO AND B.INST_NM LIKE '%'||#{INST_NM}||'%'
AND A.CMIT_SE_CD = #{CMIT_SE_CD}
AND A.CMIT_SE_CD = #{CMIT_SE_CD}
AND A.ESNTL_LINK_INST_SE_CD = #{ESNTL_LINK_INST_SE_CD}
